import random

randList = []
for x in range(15):
   nextInt = random.randint(1,25)
   while nextInt in randList:
      nextInt = random.randint(1,25)
   randList.append(nextInt)

pos = 0
while pos < 25:
  if pos in randList:
      print ("| X", end=" ")
  else:
      print ("| ", end=" ")
  pos = pos + 1
  if (pos % 5 == 0):
      print("| \n")
